            assert.equal(table.table,'auth_session','UI1/UI2 changed an undeclared physical row');changed.push(row.id);const allowed=new Set(['status','csrf_token_hash','idle_expires_at','last_seen_at','revoked_at','revoked_reason','last_ip','row_version','updated_at']);for(const column of Object.keys(old))if(!allowed.has(column))equal(old[column],row[column],'HTTP changed an immutable session column');const sent=cookieValue(record.exchange.request.headers.cookie).get('poms_session');assert(sent&&sha(sent)===old.token_hash,'HTTP modified a session outside its actual sent owned cookie');if(old.status!==row.status){assert.equal(old.status,'active');assert.equal(record.exchange.path,'/api/auth/session:logout');if(row.status==='expired')assert.equal(record.exchange.status,401);else assert(row.status==='revoked'&&row.revoked_reason==='logout'&&record.exchange.status===200);}if(old.csrf_token_hash!==row.csrf_token_hash)assert(record.exchange.path==='/api/auth/csrf-token'&&record.exchange.method==='GET'&&record.exchange.status===200);assert(Number.isInteger(row.row_version)&&row.row_version>old.row_version,'Actual session update did not advance row version');
