    const original=exactly(records,x=>x.kind==='actual-Native-final-SDK-and-SQL','Original final Native SDK/SQL record required').record;assert(original.report.binaryUnchanged&&original.report.originalNativeProducerOrRuntime&&original.report.pgCaptureComplete&&original.report.observerOnly);assert.equal(original.report.databaseBackend,journal.backend);assert.equal(original.report.binaryRawBytesSha256,exactly(sourceCap.artifacts,x=>x.kind==='native-main','Native executable capsule required').rawBytesSha256);assert(original.report.witness.complete&&original.report.witness.diagnostics.length===0&&original.report.witness.openTransactions.length===0&&original.report.witness.pendingStartCount===0);assert(Array.isArray(original.sql));
