    assert(record.sourceCapId===sourceCap.id&&record.pageUrlBeforeFirstNavigation==='about:blank'&&record.cacheDisabled&&record.CDPSessionOwner==='same-owned-browser-context'&&record.detachBeforeJourney===false&&record.headersRewritten===false&&record.oldCachedRunsReclassified===false);
    const expected=[{method:'Network.enable',params:{},ack:{}},{method:'Network.setCacheDisabled',params:{cacheDisabled:true},ack:{}}];equal(record.commands.map(({method,params,ack})=>({method,params,ack})),expected,'Both exact real CDP commands must acknowledge before navigation');equal(input.actualCDPAcknowledged,expected,'Public CDP input differs from its retained original');
